import numpy as np
from treehfd import XGBTreeHFD


def _pair_scores(model):
    df = model.get_booster().trees_to_dataframe()
    scores = {}
    for _, t in df.groupby("Tree"):
        t = t.set_index("ID")
        root = t.index[0]
        stack = [(root, [])]
        while stack:
            nid, path = stack.pop()
            f = t.loc[nid, "Feature"]
            if f == "Leaf":
                for i in range(len(path)):
                    for j in range(i + 1, len(path)):
                        a, b = path[i], path[j]
                        if a[0] != b[0]:
                            key = tuple(sorted((a[0], b[0])))
                            scores[key] = scores.get(key, 0.0) + min(a[1], b[1])
                continue
            fi = int(str(f).lstrip("f"))
            g = float(t.loc[nid, "Gain"])
            for c in ("Yes", "No"):
                stack.append((t.loc[nid, c], path + [(fi, g)]))
    return scores


def _fit_predict(model, Xtr, Xte, pairs):
    hfd = XGBTreeHFD(model)
    if len(pairs) == 0:
        hfd.fit(Xtr, interaction_order=1, verbose=False)
        out = hfd.predict(Xte, verbose=False)
        y_main = out[0] if isinstance(out, (tuple, list)) else out
        comps = {(j,): np.asarray(y_main[:, j]) for j in range(y_main.shape[1])}
        return float(hfd.eta0), comps
    arr = np.array(pairs, dtype=int).reshape(-1, 2)
    hfd.fit(Xtr, interaction_order=2, interaction_list=arr, verbose=False)
    y_main, y_o2 = hfd.predict(Xte, verbose=False)
    comps = {(j,): np.asarray(y_main[:, j]) for j in range(y_main.shape[1])}
    for k, (a, b) in enumerate(hfd.interaction_list):
        comps[(int(min(a, b)), int(max(a, b)))] = np.asarray(y_o2[:, k])
    return float(hfd.eta0), comps


def _total(eta0, comps, n):
    s = np.full(n, eta0, dtype=float)
    for v in comps.values():
        s = s + v
    return s


def decompose(model, X_train, X_test):
    scores = _pair_scores(model)
    ranked = sorted(scores, key=lambda p: -scores[p])
    if not ranked:
        return _fit_predict(model, X_train, X_test, [])
    n = len(X_train)
    rng = np.random.RandomState(0)
    idx = rng.permutation(n)
    h = n // 2
    if h < 10:
        Xa, Xv = X_train, X_train
    else:
        Xa, Xv = X_train[idx[:h]], X_train[idx[h:]]
    yv = model.predict(Xv)
    m = len(ranked)
    cands = sorted(set(k for k in [0, 1, 2, 4, 8, 16, 32, m // 2, m] if k <= m))
    errs = {}
    for k in cands:
        try:
            e, c = _fit_predict(model, Xa, Xv, ranked[:k])
            errs[k] = float(np.mean((_total(e, c, len(Xv)) - yv) ** 2))
        except Exception:
            continue
    if errs:
        best = min(errs.values())
        k = min(kk for kk, v in errs.items() if v <= best * 1.02 + 1e-12)
    else:
        k = 0
    try:
        return _fit_predict(model, X_train, X_test, ranked[:k])
    except Exception:
        return _fit_predict(model, X_train, X_test, [])
